        return appointment(`Pour bien préparer l'intervention : ${symptom.question}`, `Demande de rendez-vous pour ${symptom.label} : questions de préparation posées.${c.vehicleTag}`, null);
    }
    if (slot.day && isPast(slot, now)) {
        return appointment("Ce créneau est déjà passé. Quel autre jour et à quelle heure pourriez-vous déposer le véhicule ?", "Demande de rendez-vous : date à préciser.", null);
    }
