    if (req.switches?.atelier_complet === true && (!slot.day || isThisWeek(slot.day, now))) {
        const monday = nextMonday(now);
        return reply(`Notre atelier est complet cette semaine. Je peux noter votre demande à partir de ${humanDay(monday)} : quel jour vous arrangerait ?`, "Demande de rendez-vous : atelier complet cette semaine, semaine suivante proposée.", "rendez_vous");
    }
