    if (slot.day && slot.time) {
        const when = `${humanDay(slot.day)} à ${humanTime(slot.time)}`;
        return appointment(`J'ai bien noté votre demande : dépôt du véhicule ${when}${forWhat}. Le garage vous confirme le rendez-vous très vite. Pensez à apporter la carte grise.${motif ? "" : " Pour quelle intervention est-ce (révision, pneus, bruit, voyant…) ?"}`, `Rendez-vous atelier ${when}${forWhat}, à confirmer.${c.vehicleTag}`, parisToISO(slot.day, slot.time.h, slot.time.min));
    }
